import { ai } from './ai.js';
import { lookupOrder } from './tools.js';

/** Multi-turn order desk agent: answers questions about a customer's orders and keeps the conversation. */
export const orderAgent = ai.defineAgent({
  name: 'orderAgent',
  system:
    'You are the Northwind Supplies order desk. Answer questions about orders using the lookupOrder tool. ' +
    'Quote the status, delivery date and tracking code exactly as the tool returns them. ' +
    'If an order is not found, say so. Keep replies short.',
  tools: [lookupOrder],
});
